from PIL import Image
import numpy as np

# Create a better visualization of the flag with larger font and clearer contrast
def create_enhanced_flag():
    # Process the images to extract the XOR result more clearly
    img1 = Image.open('/home/ctfplayer/ctf_files/image1.png')
    img2 = Image.open('/home/ctfplayer/ctf_files/image2.png')

    # Convert images to numpy arrays for processing
    data1 = np.array(img1)
    data2 = np.array(img2)

    # XOR the two images
    xor_result = np.bitwise_xor(data1, data2)

    # Get dimensions, handling either grayscale or RGB
    if len(xor_result.shape) == 3:
        height, width, _ = xor_result.shape
    else:
        height, width = xor_result.shape

    # Create larger visualization with better downsampling
    scale_factor = 5
    result_img = Image.new('RGB', (width * scale_factor, height * scale_factor), color='white')

    for y in range(height):
        for x in range(width):
            # Check if there's any non-zero value at this pixel
            if len(xor_result.shape) == 3:
                has_value = np.any(xor_result[y, x] > 0)
            else:
                has_value = xor_result[y, x] > 0

            if has_value:
                # Draw a larger black pixel (5x5) for better visibility
                for dy in range(scale_factor):
                    for dx in range(scale_factor):
                        if 0 <= y * scale_factor + dy < height * scale_factor and 0 <= x * scale_factor + dx < width * scale_factor:
                            result_img.putpixel((x * scale_factor + dx, y * scale_factor + dy), (0, 0, 0))

    # Save the enhanced image
    result_img.save('/home/ctfplayer/enhanced_flag.png')
    print("Enhanced flag saved to enhanced_flag.png")

    # Create clear text visualization using ASCII characters
    ascii_img = []
    downsample = 2  # Downsample for terminal display
    for y in range(0, height, downsample):
        line = []
        for x in range(0, width, downsample):
            # Check if any of the pixels in this downsampled block have non-zero values
            has_value = False
            for dy in range(downsample):
                for dx in range(downsample):
                    if y+dy < height and x+dx < width:
                        if len(xor_result.shape) == 3:
                            pixel_has_value = np.any(xor_result[y+dy, x+dx] > 0)
                        else:
                            pixel_has_value = xor_result[y+dy, x+dx] > 0

                        if pixel_has_value:
                            has_value = True
                            break
                if has_value:
                    break

            # Use more visible characters
            if has_value:
                line.append('█')  # Use a solid block character for better visibility
            else:
                line.append(' ')
        ascii_img.append(''.join(line))

    # Save the ASCII art
    with open('/home/ctfplayer/clear_flag.txt', 'w') as f:
        f.write('\n'.join(ascii_img))
    print("Clear flag text saved to clear_flag.txt")

# Run the enhanced flag extraction
create_enhanced_flag()
